from typing import List, Dict, Any
import csv
import io
import re
from collections import Counter

def parse_csv(raw_csv: str):
    if raw_csv is None:
        return {"columns": [], "rows": []}

    text = raw_csv.replace("\r\n", "\n").replace("\r", "\n")
    if not text.strip():
        return {"columns": [], "rows": []}

    lines = text.split("\n")

    def is_preamble_line(line: str) -> bool:
        s = line.strip()
        if not s:
            return True
        if s.startswith("#"):
            return True
        if re.match(r"^(sep=|delimiter=)", s, re.I):
            return True
        if re.match(r"^(generated|exported|report|date|time)\b", s, re.I) and "," not in s:
            return True
        return False

    start = 0
    while start < len(lines) and is_preamble_line(lines[start]):
        start += 1

    data = "\n".join(lines[start:])

    def sniff_dialect(sample: str):
        try:
            return csv.Sniffer().sniff(sample, delimiters=[",", ";", "\t", "|"])
        except Exception:
            class D(csv.Dialect):
                delimiter = ","
                quotechar = '"'
                doublequote = True
                skipinitialspace = False
                lineterminator = "\n"
                quoting = csv.QUOTE_MINIMAL
            return D

    dialect = sniff_dialect(data[:8192] if data else "")
    reader = csv.reader(io.StringIO(data), dialect)

    rows: List[List[str]] = []
    for row in reader:
        if not row:
            continue
        rows.append([str(v) for v in row])

    if not rows:
        return {"columns": [], "rows": []}

    expected_width = 0
    widths = [len(r) for r in rows[: min(len(rows), 20)] if r]
    if widths:
        expected_width = Counter(widths).most_common(1)[0][0]
    else:
        expected_width = len(rows[0])

    header = rows[0]
    if len(header) < expected_width:
        header = header + [""] * (expected_width - len(header))
    elif len(header) > expected_width:
        expected_width = len(header)

    normalized_rows: List[List[str]] = []
    for r in rows[1:]:
        if len(r) < expected_width:
            r = r + [""] * (expected_width - len(r))
        elif len(r) > expected_width:
            r = r[:expected_width - 1] + [",".join(r[expected_width - 1:])]
        normalized_rows.append(r)

    return {"columns": header, "rows": normalized_rows}
